var a={en:`A release attracts 8,000 visits/minute. Public pages need p95 under 300 ms, yet only 400 seats exist. Infrastructure budget is limited.`,ua:`Старт продажів залучає 8 000 відвідувань/хв. Для публічних сторінок потрібен p95 до 300 мс, але є лише 400 місць. Бюджет обмежений.`};var t={en:[`Mark hot read paths separately from authoritative writes.`,`Select justified caching, admission control and rate limits.`,`Define last-seat stress testing and overload messages.`],ua:[`Познач гарячі читання окремо від авторитетних записів.`,`Обери виправдані кешування, контроль допуску й ліміти.`,`Визнач стрес-тест останнього місця й повідомлення при перевантаженні.`]};var i=[{en:`No cache decides the final seat allocation.`,ua:`Кеш не вирішує остаточний розподіл місць.`},{en:`Confirmed seats never exceed 400.`,ua:`Підтверджених бронювань ніколи не більше 400.`}];var n={scenario:a,tasks:t,checks:i};export{i as checks,n as default,a as scenario,t as tasks};